test("period export scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  await ui.setSetting(pg_uma, "terms", "30");
  await ui.setSetting(pg_uma, "late-pct", "10.00");
  expect(await ui.setRole(pg_uma, "vic", "viewer")).toBe(true);
  await ui.setSetting(pg_uma, "note-threshold", "1.00");
  expect(await ui.addHoliday(pg_uma, "2026-04-03")).toBe(true);
  await ui.setSetting(pg_uma, "grace-C", "5");
  await ui.loadSheet(pg_uma, `${sheet}-p`);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "5.00"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A"}));
  const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "12.50"}));
  expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
  await ui.loadSheet(pg_uma, sheet);
  await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
  await ui.setSetting(pg_uma, "pot", "7.77");
  expect(await ui.setSettingDated(pg_uma, "rounding", "half-up", "2026-03-10", "half-up")).toBe(true);
  await ui.setSetting(pg_uma, "escalate-after", "1");
  await ui.setSetting(pg_uma, "score-mid", "0");
  await ui.setSetting(pg_uma, "score-high", "5");
  await ui.setSetting(pg_uma, "pending-sla", "1");
  expect(await ui.setRole(pg_uma, "wes", "restricted")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00", "from": "2026-03-10", "to": "2026-03-12"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C"}));
  expect(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C", "tags": "a"})).toBeNull();
  expect(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C", "contact": "ben@x", "tags": "c"})).toBeNull();
  expect(await ui.setApprover(pg_uma, p_ben, "vic")).toBe(true);
  expect(await ui.periodAction(pg_uma, "P2", "close")).toBe(true);
  const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "12.50", "date": "2026-03-01", "note": "n", "tags": "a, B"}));
  expect(await ui.addAlias(pg_uma, p_ben, " ada ")).toBe(false);

