-- The sheet's terms: the number of days after its date a claim is due by. An OPEN claim whose
-- due-by is before the sheet's today is overdue.
ALTER TABLE sheet ADD COLUMN terms INT DEFAULT 14 NOT NULL;
-- A person's own terms in days; null when the person has none and takes their grade's (or the
-- sheet's) terms. A claim's due-by is fixed when it is added from the first of the person's own
-- terms, their grade's terms and the sheet's terms in force on its date.
ALTER TABLE person ADD COLUMN terms INT CHECK (terms >= 0);
-- A person's own terms are dated: the terms on the person row apply from the beginning of time; each
-- later terms are recorded here from their date, one per date, and hold from that date until the next.
-- A terms of -1 records that the person has no terms of their own from that date.
CREATE TABLE person_terms (
    person_id BIGINT  NOT NULL REFERENCES person (id),
    from_date DATE    NOT NULL,
    terms     INTEGER NOT NULL CHECK (terms >= -1),
    PRIMARY KEY (person_id, from_date)
);
